#[test]
fn paren_base_slot_loan_flushes_before_branch_spawn_and_delete() { for (s, w, d) in [("m := map[string]int{\"a\": 0}\nch := make(chan map[string]int, 1)\nn := &(m)[\"a\"]\nif true { n = 7\nch <- move m }", "(m)[\"a\"] = n", "ch <- m"), ("x := h{m: map[string]int{\"a\": 0}}\nn := &((x).m)[\"a\"]\nif false { n = 7 } else { delete(x.m, \"a\") }", "(x.m)[\"a\"] = n", "delete(x.m, \"a\")")] { let g = hy_emit::emit_go(&hy_syntax::parse_file("t.hy", &format!("struct h {{ m map[string]int }}\nfn main() {{\n{s}\n}}\n")).unwrap()).unwrap(); assert!(g.find(w).unwrap() < g.find(d).unwrap() && !g.ends_with(&format!("\t{w}\n}}\n")), "{g}"); } }
